<template><view :data-skin="scenicSkin" class="visual-page archive-shell"><SceneBackdrop :src="backgrounds[theme]" :shade=".65" fractured/><TopBar :title="title" :eyebrow="code" @back="back" @settings="settings"/><AssetPanel class="archive-body"><text class="section-label">{{code}}</text><text class="visual-title">{{title}}</text><AssetImage class="visual-divider" :src="uiAssets.decorations.divider" fit="contain"/><text class="visual-copy">{{description}}</text><AssetButton @click="back">返回</AssetButton></AssetPanel></view></template><script setup lang="ts">import TopBar from '../TopBar.vue';import AssetImage from './AssetImage.vue';import AssetPanel from './AssetPanel.vue';import AssetButton from './AssetButton.vue';import SceneBackdrop from './SceneBackdrop.vue';import {backgrounds} from '../../data/backgrounds';import {uiAssets} from '../../config/ui-assets';withDefaults(defineProps<{title:string;code:string;theme?:keyof typeof backgrounds;description?:string}>(),{theme:'engagement',description:'请从剧情中进入这一页。'});function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.reLaunch({url:'/pages/home/index'})}function settings(){uni.navigateTo({url:'/pages/settings/index'})}</script><style scoped>.archive-body{position:relative;width:min(780px,88vw);margin:10vh auto}.archive-body .visual-title{display:block;margin:25px 0}.archive-body .visual-copy{display:block;margin-bottom:30px}.archive-body .asset-button{width:160px}</style>